(async () => {
  try {
    const me = String(Inputs.userId || '');
    const stepId = String(Inputs.stepId || '');
    const file = String(Inputs.file || '');
    if (!me || !stepId || !file) throw new Error('missing user, step or file');
    const steps = await Noodl.Records.query('Step', { objectId: { equalTo: stepId } }, { limit: 2, plain: true });
    const step = steps.length === 1 ? steps[0] : null;
    if (!step || step.learner !== me || step.shared !== true || step.kind !== 'homework') throw new Error('not a shared homework step of the caller');
    const listed = (Array.isArray(step.resources) ? step.resources : []).some((r) => r && r.file === file);
    if (!listed) throw new Error('that step lists no such file');
    Outputs.name = file;
  } catch (e) {
    console.error('[dbu:resourceLink]', String((e && e.message) || e));
    Outputs.refused();
  }
})();
